begin;
select plan(18);
select ok((select bool_and(relrowsecurity and relforcerowsecurity) from pg_class where oid in('private.launch_batches'::regclass,'private.launch_batch_items'::regclass,'private.launch_batch_other_proofs'::regclass,'private.catalog_background_claim_schedule'::regclass)),'batch commands, proof fences and claim pacing all have forced RLS');
select ok(not has_table_privilege('authenticated','private.launch_batches','select,insert,update,delete') and not has_table_privilege('service_role','private.launch_batch_items','select,insert,update,delete'),'batch payloads are inaccessible outside protected RPCs');
select ok(has_function_privilege('service_role','public.service_accept_launch_batch(uuid,uuid,uuid,jsonb,jsonb)','execute') and not has_function_privilege('authenticated','public.service_accept_launch_batch(uuid,uuid,uuid,jsonb,jsonb)','execute') and not has_function_privilege('authenticated','public.service_retry_launch_batch_admission(uuid,uuid,uuid,jsonb,jsonb,uuid)','execute') and not has_function_privilege('service_role','private.accept_launch_batch(uuid,uuid,uuid,jsonb,jsonb,boolean,uuid)','execute'),'only trusted Edge can admit a prepared batch');
select ok(has_function_privilege('service_role','public.service_claim_launch_batch_admission_recovery(integer)','execute') and not has_function_privilege('authenticated','public.service_claim_launch_batch_admission_recovery(integer)','execute') and not has_function_privilege('anon','public.service_retry_launch_batch_admission(uuid,uuid,uuid,jsonb,jsonb,uuid)','execute'),'pending admission leases and retry authority are service-only');
select ok(has_function_privilege('service_role','public.service_continue_launch_batch_recovery()','execute') and not has_function_privilege('authenticated','public.service_continue_launch_batch_recovery()','execute') and not has_function_privilege('anon','public.service_continue_launch_batch_recovery()','execute'),'bounded recovery continuation cannot be invoked by browser or anonymous callers');
select ok(has_function_privilege('authenticated','public.get_launch_batch(uuid,uuid)','execute') and has_function_privilege('authenticated','public.list_launch_batches(uuid,integer,timestamptz,uuid)','execute'),'authenticated readers use actor-scoped batch projections');
select ok(has_function_privilege('authenticated','public.cancel_launch_batch(uuid,uuid,uuid,uuid)','execute') and not has_function_privilege('anon','public.cancel_launch_batch(uuid,uuid,uuid,uuid)','execute'),'cancellation requires an authenticated expected-actor fence');
select ok(not has_function_privilege('service_role','private.apply_launch_batch_cancellation(uuid,integer)','execute') and not has_function_privilege('authenticated','private.apply_launch_batch_cancellation(uuid,integer)','execute'),'no external caller can bypass persisted cancellation scope');
select ok(has_function_privilege('service_role','public.service_publish_launch_batch_other_generation(uuid,uuid,uuid,text,text)','execute') and not has_function_privilege('authenticated','public.service_publish_launch_batch_other_generation(uuid,uuid,uuid,text,text)','execute'),'source-proven publication is a service-only lease-fenced command');
select ok(not has_table_privilege('service_role','private.launch_batch_other_proofs','insert,update,delete'),'service clients cannot forge source proof rows');
select ok(has_function_privilege('service_role','public.service_interrupt_launch_generation_with_backoff(uuid,uuid,uuid,text,text,text,integer)','execute') and not has_function_privilege('authenticated','public.service_interrupt_launch_generation_with_backoff(uuid,uuid,uuid,text,text,text,integer)','execute') and not has_function_privilege('anon','public.service_interrupt_launch_generation_with_backoff(uuid,uuid,uuid,text,text,text,integer)','execute'),'catalog provider cooldown uses a service-only fenced command');
select ok(has_function_privilege('service_role','public.service_record_launch_batch_other_failure(uuid,uuid,uuid,text,text,text,boolean,integer)','execute') and not has_function_privilege('authenticated','public.service_record_launch_batch_other_failure(uuid,uuid,uuid,text,text,text,boolean,integer)','execute') and not has_function_privilege('anon','public.service_record_launch_batch_other_failure(uuid,uuid,uuid,text,text,text,boolean,integer)','execute') and to_regprocedure('public.service_record_launch_batch_other_failure(uuid,uuid,uuid,text,text,text,boolean)')is null,'persisted provider backoff has one service-only entry point');
select ok(exists(select 1 from pg_trigger where tgname='launch_batch_other_proof' and tgrelid='public.team_launch_generations'::regclass),'every publication path enforces batch Other source proof');
select columns_are('public','analytics_launch_batches',array['batch_id','team_id','actor_id','request_key','created_at','cancel_requested_at','ordinal','launch_id','child_request_key','generation_id','admission','error_code','cancel_pending','cancel_error_code','cancel_next_attempt_at','admission_attempts','admission_next_attempt_at','member_updated_at','member_count','generation_state','generation_stage','generation_error_code','generation_updated_at','video_set_id','video_state','video_requested_count','video_registered_count','video_updated_at'],'diagnostics contain only identifiers, outcomes and timestamps');
select ok(not has_table_privilege('authenticated','public.analytics_launch_batches','select') and not has_table_privilege('service_role','public.analytics_launch_batches','select'),'diagnostic command view is not a product data endpoint');
select throws_ok($$select private.validate_launch_batch_intent('d0530000-0000-4000-8000-000000000001','d0530000-0000-4000-8000-000000000002','{"teamId":"d0530000-0000-4000-8000-000000000001","requestKey":"d0530000-0000-4000-8000-000000000002","items":[{"launchId":"d0530000-0000-4000-8000-000000000003","childRequestKey":"d0530000-0000-4000-8000-000000000004","expectedVersion":"9223372036854775808"}]}')$$,'22023','INVALID_INPUT','batch CAS cannot overflow the authoritative bigint version');
select is((select count(*)::integer from pg_trigger where tgrelid in('private.launch_batches'::regclass,'private.launch_batch_items'::regclass,'private.launch_batch_other_proofs'::regclass,'private.catalog_background_claim_schedule'::regclass,'private.catalog_rename_requests'::regclass,'private.catalog_rename_absent_commands'::regclass,'private.catalog_name_aliases'::regclass)and tgname='task_cleanup_reference_fence'and tgenabled='O'and tgfoid='private.guard_task_cleanup_reference()'::regprocedure),7,'every new durable consumer uses the real task-file reference fence');
select ok(private.task_cleanup_coverage_verified(),'durable launches and canonical names retain complete cleanup coverage');
select * from finish();
rollback;
